package tv.vela.launcher;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.util.*;import java.io.*;import java.lang.reflect.*;

/** Owned channels: bounded time queries, remote navigation across blocks/pages, gaps and view persistence. */
public final class AndroidTvTimelineTest extends Instrumentation {
 private LiveTvActivity tv;
 private interface Ready{boolean ready()throws Exception;}
 private void check(boolean value,String why){if(!value)throw new AssertionError(why);}
 private Object get(Object o,String name)throws Exception{if(o instanceof ScreenActivity)o=((ScreenActivity)o).screen;for(Class<?> type=o.getClass();type!=null;type=type.getSuperclass())try{Field f=type.getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(NoSuchFieldException next){}throw new NoSuchFieldException(name);}
 private void ui(Runnable r){runOnMainSync(r);waitForIdleSync();}
 private void await(Ready r,String why)throws Exception{long until=SystemClock.elapsedRealtime()+20000;while(SystemClock.elapsedRealtime()<until){waitForIdleSync();if(r.ready())return;Thread.sleep(60);}throw new AssertionError(why);}
 private void restore(SharedPreferences p,Map<String,?> values){SharedPreferences.Editor e=p.edit().clear();for(Map.Entry<String,?> item:values.entrySet()){Object v=item.getValue();String k=item.getKey();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Set)e.putStringSet(k,new HashSet<>((Set<String>)v));}e.commit();}
 private String stamp(long seconds){java.text.SimpleDateFormat d=new java.text.SimpleDateFormat("yyyyMMddHHmmss Z",Locale.ROOT);d.setTimeZone(TimeZone.getTimeZone("UTC"));return d.format(new Date(seconds*1000));}
 private void chooseView(Context c,boolean guide)throws Exception{
  SettingsActivity settings=(SettingsActivity)startActivitySync(new Intent(c,SettingsActivity.class).putExtra("page",22).putExtra("returnToCaller",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Object panel=get(settings,"view");List<View> choices=(List<View>)get(panel,"rows");ui(()->choices.get(guide?0:1).performClick());key(KeyEvent.KEYCODE_BACK);await(()->tv.hasWindowFocus()&&(Boolean)get(tv,"timelineMode")==guide&&!(Boolean)get(tv,"loading"),"TV Settings choice not applied");
 }
 private void key(int code){sendKeyDownUpSync(code);waitForIdleSync();}
 private long protectedBand(Rect clip,Rect help)throws Exception{Thread.sleep(120);Bitmap image=getUiAutomation().takeScreenshot();check(image!=null,"Native screenshot unavailable");long hash=0xcbf29ce484222325L;try{for(int y=clip.bottom+2;y<help.bottom;y++)for(int x=clip.left;x<clip.right;x++)hash=(hash^image.getPixel(x,y))*0x100000001b3L;}finally{image.recycle();}return hash;}
 private void categoriesStayBounded()throws Exception{
  List<TvCatalogCache.Group> groups=(List<TvCatalogCache.Group>)get(tv,"groups");ListView list=(ListView)get(tv,"groupList");FrameLayout viewport=(FrameLayout)get(tv,"categoryViewport");TextView help=(TextView)get(tv,"status");BaseAdapter adapter=(BaseAdapter)get(tv,"groupAdapter");
  ui(()->{groups.clear();for(int i=0;i<180;i++)groups.add(new TvCatalogCache.Group("scroll-"+i,i==8?"Documentaries & Kids":"Categoría "+i,0));adapter.notifyDataSetChanged();list.setSelection(0);list.requestFocus();});key(KeyEvent.KEYCODE_DPAD_DOWN);Rect clip=new Rect(),protectedHelp=new Rect();viewport.getGlobalVisibleRect(clip);help.getGlobalVisibleRect(protectedHelp);check(clip.bottom<protectedHelp.top,"Categories overlap remote help");long before=protectedBand(clip,protectedHelp);
  for(int i=0;i<56;i++){key(KeyEvent.KEYCODE_DPAD_DOWN);if(i%8==7){check(viewport.getHeight()==570&&list.getHeight()==570&&list.getChildCount()<=11,"Scrolling expanded category viewport or view count");for(int n=0;n<list.getChildCount();n++){Rect visible=new Rect();if(list.getChildAt(n).getGlobalVisibleRect(visible))check(clip.contains(visible),"Category row escaped clipped viewport");}check(protectedBand(clip,protectedHelp)==before,"Scrolling categories painted over remote help");}}
  for(int i=0;i<35;i++)key(KeyEvent.KEYCODE_DPAD_UP);check(list.getFirstVisiblePosition()>0&&list.hasFocus(),"Long category list did not scroll with remote");check(protectedBand(clip,protectedHelp)==before,"Returning through categories painted over remote help");
 }

 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();Context c=getTargetContext();SharedPreferences p=LiveTvData.prefs(c),epg=c.getSharedPreferences("xmltv",0);Map<String,?> before=new HashMap<>(p.getAll()),epgBefore=new HashMap<>(epg.getAll());String source="";try{
  check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("sdk"),"Owned emulator required");Locale.setDefault(new Locale("es","ES"));p.edit().putString("tv-view","channels").commit();
  M3uClient client=new M3uClient(c);client.configure("https://example.invalid/owned-timeline.m3u8","",false);source=M3uClient.identity(c);TvCatalogCache cache=new TvCatalogCache(c);List<LiveTvData.Channel> all=new ArrayList<>();
  try(TvCatalogCache.Writer writer=cache.writer(source)){for(int i=1;i<=24;i++){LiveTvData.Channel ch=new LiveTvData.Channel("guide-"+i,"Canal "+i,"Pruebas","",Collections.singletonList("https://example.invalid/live.m3u8"));all.add(ch);writer.add(ch,false);}writer.commit("{}");}
  long now=System.currentTimeMillis()/1000,from=TvTimelineView.present(now);StringBuilder xml=new StringBuilder("<tv>");for(int i=1;i<=24;i++){xml.append("<channel id='guide-").append(i).append("'><display-name>Canal ").append(i).append("</display-name></channel>");if(i==6)continue;for(int n=0;n<(i==24?200:48);n++){long start=from-1800+n*(i==24?60:1800),end=start+(i==24?60:1800);xml.append("<programme channel='guide-").append(i).append("' start='").append(stamp(start)).append("' stop='").append(stamp(end)).append("'><title>Programa ").append(n).append(" &amp; canal ").append(i).append("</title></programme>");}}xml.append("</tv>");
  XmlTvGuide guide=new XmlTvGuide(c);guide.configure(XmlTvGuide.DEFAULT_URL);guide.importGuide(new ByteArrayInputStream(xml.toString().getBytes("UTF-8")),LiveTvData.hash(XmlTvGuide.DEFAULT_URL),now);
  Map<String,List<LiveTvData.Programme>> window=guide.window(all,from);check(window.size()==5&&!window.containsKey("guide-7"),"More than six channel schedules read, or missing data fabricated");for(List<LiveTvData.Programme> list:window.values())for(LiveTvData.Programme show:list)check(show.end>from&&show.start<from+TvTimelineView.SECONDS,"Outside-window programme retained");check(guide.window(Collections.singletonList(all.get(23)),from).get("guide-24").size()==TvTimelineView.MAX_PROGRAMMES,"Per-channel programme limit missing");
  tv=(LiveTvActivity)startActivitySync(new Intent(c,LiveTvActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(()->tv.catalog!=null&&!(Boolean)get(tv,"loading"),"Owned channels unavailable");check(((List<?>)get(tv,"cards")).size()==12,"Existing channel grid changed");check(((View)get(tv,"guideMode")).getVisibility()==View.GONE&&((View)get(tv,"gridMode")).getVisibility()==View.GONE,"View selectors remain on TV");chooseView(c,true);
  await(()->((Map<?,?>)get(tv,"timelineProgrammes")).size()>=5,"Timeline did not load");TvTimelineView view=(TvTimelineView)get(tv,"timeline");check(view.hasFocus()&&view.getChildCount()==6&&((List<?>)get(tv,"cards")).isEmpty(),"Timeline state focus="+view.hasFocus()+", children="+view.getChildCount()+", cards="+((List<?>)get(tv,"cards")).size()+", visibility="+view.getVisibility()+", window="+tv.hasWindowFocus());check(tv.playback==null,"Guide autoplayed");
  await(()->!(Boolean)get(tv,"guideLoading"),"Source guide still loading");Map<String,LiveTvData.Guide> filled=new HashMap<>((Map<String,LiveTvData.Guide>)get(tv,"guide"));LiveTvData.Guide gap=new LiveTvData.Guide();gap.add(new LiveTvData.Programme(now-600,now+1200,"Source fills missing current programme"),now);filled.put("guide-6",gap);
  ui(()->{try{Field f=LiveTvActivity.class.getDeclaredField("guide");f.setAccessible(true);f.set(tv,filled);Method m=LiveTvActivity.class.getDeclaredMethod("loadTimeline",boolean.class);m.setAccessible(true);m.invoke(tv,false);}catch(Exception e){throw new RuntimeException(e);}});
  await(()->{Map<String,List<LiveTvData.Programme>> values=(Map<String,List<LiveTvData.Programme>>)get(tv,"timelineProgrammes");return values.containsKey("guide-6")&&!values.get("guide-6").isEmpty();},"Available source programme was not used for an XMLTV gap");
  key(KeyEvent.KEYCODE_DPAD_RIGHT);check(view.programme()!=null&&view.programme().start>now,"Right did not select the next programme");key(KeyEvent.KEYCODE_DPAD_CENTER);check(((FrameLayout)get(tv,"dialog")).getVisibility()==View.VISIBLE&&tv.playback==null,"Future programme played automatically");key(KeyEvent.KEYCODE_BACK);ui(view::requestFocus);
  ui(()->{try{Method m=LiveTvActivity.class.getDeclaredMethod("showUpcoming",LiveTvData.Channel.class,LiveTvData.Programme.class);m.setAccessible(true);m.invoke(tv,tv.selected,new LiveTvData.Programme(now-1800,now-60,"Ended programme"));}catch(Exception e){throw new RuntimeException(e);}});FrameLayout detail=(FrameLayout)get(tv,"dialog");StringBuilder labels=new StringBuilder();for(int i=0;i<detail.getChildCount();i++)if(detail.getChildAt(i) instanceof TextView)labels.append(((TextView)detail.getChildAt(i)).getText());check(labels.toString().contains("ya ha terminado")&&tv.playback==null,"Past programme described as upcoming or played as catch-up");key(KeyEvent.KEYCODE_BACK);ui(view::requestFocus);
  for(int i=0;i<6;i++)key(KeyEvent.KEYCODE_DPAD_DOWN);check((Integer)get(tv,"timelineOffset")==6&&tv.selected.id.equals("guide-7"),"Down did not cross six-channel block");for(int i=0;i<6;i++)key(KeyEvent.KEYCODE_DPAD_DOWN);await(()->(Integer)get(tv,"page")==1&&!(Boolean)get(tv,"loading"),"Down did not cross catalog page");check(tv.selected.id.equals("guide-13"),"Wrong channel after catalog page");key(KeyEvent.KEYCODE_DPAD_UP);await(()->(Integer)get(tv,"page")==0&&!(Boolean)get(tv,"loading"),"Up did not return to previous page");check(tv.selected.id.equals("guide-12"),"Up lost spatial focus at catalog boundary");
  TextView later=(TextView)get(tv,"guideLater");ui(later::performClick);await(()->(Long)get(tv,"timelineStart")==from+5400,"Future window did not shift");check(tv.playback==null,"Moving time started playback");TextView present=(TextView)get(tv,"guideNow");ui(present::performClick);await(()->(Long)get(tv,"timelineStart")==TvTimelineView.present(System.currentTimeMillis()/1000),"Now did not reset time");
  chooseView(c,false);check(((List<?>)get(tv,"cards")).size()==12&&view.getVisibility()==View.GONE,"Return to channel grid failed");chooseView(c,true);check(LiveTvData.guideView(c),"Guide preference not saved");Thread.sleep(500);waitForIdleSync();categoriesStayBounded();ui(tv::finish);
  result.putString("result","PASS six-channel/three-hour SQL window, 32-programme bound, honest gaps and source fallback, unchanged 12-channel grid, real remote future selection and honest ended-programme details without autoplay, vertical navigation across six-channel blocks and catalog pages, spatial focus on return, time shift/Now, saved display preference and 180 recycled categories scrolled with the real remote without changing a pixel of the help area.");
 }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{if(tv!=null)ui(tv::finish);if(!source.isEmpty())new TvCatalogCache(c).remove(source);restore(p,before);restore(epg,epgBefore);}finish(result.containsKey("error")?1:-1,result);}
}
